SELECT  FROM resolved_case c
JOIN ticket t ON t.id=c.source_ticket_id

    c.deleted=FALSE
    AND c.status=#{status}
    AND t.ticket_no=#{sourceTicketNo}

        AND (c.title LIKE CONCAT('%',#{keyword},'%')
          OR c.problem LIKE CONCAT('%',#{keyword},'%'))


ORDER BY c.created_at DESC,c.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM resolved_case c JOIN ticket t ON t.id=c.source_ticket_id

    c.deleted=FALSE
    AND c.status=#{status}
    AND t.ticket_no=#{sourceTicketNo}

        AND (c.title LIKE CONCAT('%',#{keyword},'%')
          OR c.problem LIKE CONCAT('%',#{keyword},'%'))
